 C.need(value.get('status')=='PASS_NATIVE574_SELECTED_ORPHAN_CLEANUP' and value.get('base_count')==574 and value.get('counts')==[576,575] and value.get('selected')==['cachy-asahi-cache'],'genuine selected Cache matrix required')
