 cases=value.get('cases',{});C.need(set(cases)=={'noop','cancel','foreign_lock','normal','stale'} and cases['noop'].get('status')=='NOT_APPLIED_NO_SELECTION' and cases['cancel'].get('status')=='CANCELLED_NOT_APPLIED' and all(cases[n].get('status')=='FAIL' for n in ('foreign_lock','stale')),'all explicit no-op/cancel/refusal cases required')
