 graph=value.get('actual_reason_graph',{});cache=graph.get('cachy-asahi-cache',{});runtime=graph.get('cachy-asahi-repository-runtime',{});C.need(cache.get('candidate') is True and cache.get('reason')=='dependency' and cache.get('required_by')==cache.get('optional_required_by')==[] and runtime.get('reason')=='dependency' and runtime.get('required_by')==['cachy-asahi-cache'],'actual dependency leaf/needed Runtime graph required')
 normal=cases['normal'];C.need(normal.get('status')=='PASS_SELECTED_CATALOG_ORPHAN_REMOVAL_IN_OWNED_COPY' and normal.get('prepared_add')=={} and normal.get('prepared_remove')=={'cachy-asahi-cache':'0.2.0-1'} and normal.get('commit_started') is True and normal.get('packages_committed') is True and normal.get('dependency_checks')=='ORDINARY_LIBALPM','one exact ordinary ALPM removal commit required')
